INSERT OR REPLACE INTO profile_blocks (key, label, description, sort_order) VALUES ('personalDetails', 'Personal Details', 'Who you are and how employers reach you. Includes the voluntary EEO / self-identification section.', 1);
INSERT OR REPLACE INTO profile_blocks (key, label, description, sort_order) VALUES ('workEligibility', 'Work Eligibility', 'Where and under what legal arrangement you can work.', 2);
INSERT OR REPLACE INTO profile_blocks (key, label, description, sort_order) VALUES ('workPreferences', 'Work Preferences', 'Pay, format, schedule, and mobility. The pay floor is enforced here.', 3);
INSERT OR REPLACE INTO profile_blocks (key, label, description, sort_order) VALUES ('professionalProfile', 'Professional Profile', 'Education, seniority, skills, and work history that the match score reads.', 4);
INSERT OR REPLACE INTO profile_blocks (key, label, description, sort_order) VALUES ('company', 'Company Fit', 'The kind of company, team, and environment you work best in.', 5);
INSERT OR REPLACE INTO profile_blocks (key, label, description, sort_order) VALUES ('career', 'Career & Motivation', 'Where you are in the search and what you are looking for.', 6);

